const fmt=(v,withTime=true)=>v?new Intl.DateTimeFormat('en-MY',withTime?{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',hour12:false}:{day:'2-digit',month:'short',year:'numeric'}).format(new Date(v)):'—';
