const STORE='itransfer_mvp_v1';
let state=loadState(); let activeRole='requester'; let requesterMode='dashboard';
function loadState(){try{const x=JSON.parse(localStorage.getItem(STORE));if(x?.transfers)return x}catch(e){} return {transfers:structuredClone(seedTransfers),version:1};}
function saveState(){localStorage.setItem(STORE,JSON.stringify(state));renderNav();}
function resetState(){state={transfers:structuredClone(seedTransfers),version:1};saveState();render();toast('Demo reset','Synthetic seed records restored.');}
function actor(role=activeRole){return `${ROLES[role].name} · ${ROLES[role].subtitle}`}
function addAudit(t,action,role=activeRole){const at=nowIso();t.audit.unshift({at,actor:actor(role),action});t.updatedAt=at;}
function interstate(t){return t.destinationState!=='Kedah'}
function statusChip(s){return `<span class="chip ${s}">${STATUS_LABELS[s]||s}</span>`}
function metric(label,value,note,cls=''){return `<div class="metric ${cls}"><span class="label">${label}</span><strong>${value}</strong><small>${note}</small></div>`}
function pageHead(title,desc,actions=''){return `<div class="page-head"><div><h2>${title}</h2><p>${desc}</p></div><div class="actions">${actions}</div></div>`}
function tableRows(items,action='view'){return items.map(t=>`<tr><td><button class="link-btn ref" data-detail="${t.id}">${t.id}</button><span class="sub">${fmt(t.requestedAt)}</span></td><td><span class="patient">${escapeHtml(t.patient)}</span><span class="sub">${escapeHtml(t.unit)}</span></td><td><b>${escapeHtml(t.destination)}</b><span class="sub">${escapeHtml(t.destinationState)}${interstate(t)?' · Interstate':''}</span></td><td><span class="priority ${t.triage.toLowerCase()}">${t.triage}</span></td><td>${statusChip(t.status)}</td><td>${t.ambulance?escapeHtml(t.ambulance):'<span class="muted">Not assigned</span>'}</td><td><button class="btn small" data-detail="${t.id}">${action==='manage'?'Manage':'View'}</button></td></tr>`).join('')}
function transferTable(items,action='view'){return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Reference</th><th>Patient / unit</th><th>Destination</th><th>Priority</th><th>Status</th><th>Ambulance</th><th></th></tr></thead><tbody>${tableRows(items,action)||`<tr><td colspan="7"><div class="empty">No transfers in this view.</div></td></tr>`}</tbody></table></div>`}

function renderNav(){
  const pending=state.transfers.filter(t=>t.status==='medical').length;
  roleNav.innerHTML=`<div class="nav-label">Role-based views</div>`+Object.entries(ROLES).map(([k,r])=>`<button class="nav-item ${k===activeRole?'active':''}" data-role="${k}"><span class="nav-icon">${r.icon}</span><span>${r.label}</span>${k==='physician'&&pending?`<span class="nav-badge">${pending}</span>`:''}</button>`).join('');
  noticeCount.textContent=pending+1;
}
function setRole(role){activeRole=role;requesterMode='dashboard';const r=ROLES[role];pageTitle.textContent=r.label;eyebrow.textContent=r.eyebrow;profileName.textContent=r.name;profileRole.textContent=r.subtitle;document.querySelector('.avatar').textContent=r.initials;profileMenu.classList.remove('open');sidebar.classList.remove('open');render();}
function render(){renderNav();({requester:renderRequester,operator:renderOperator,physician:renderPhysician,manager:renderManager,pilot:renderPilot,live:renderLive}[activeRole])();bindCommon();}
function bindCommon(){document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>openDetail(b.dataset.detail));}

function renderRequester(){
  if(requesterMode==='form'){renderBookingForm();return}
  const mine=state.transfers.filter(t=>t.requestingFacility==='Hospital Sultanah Bahiyah');
  const open=mine.filter(t=>!['completed','cancelled','rejected'].includes(t.status));
  app.innerHTML=pageHead('Ward transfer requests','Submit and follow interfacility transfers originating from HSB.',`<button class="btn primary" id="newBooking">＋ New transfer request</button>`)+
    `<div class="grid metrics">${metric('Open requests',open.length,'Across HSB wards','live')}${metric('Awaiting approval',mine.filter(t=>['new','medical','clarification'].includes(t.status)).length,'Medical or operational','warn')}${metric('In transit',mine.filter(t=>t.status==='active').length,'Live missions','live')}${metric('Completed today',mine.filter(t=>t.status==='completed').length,'Synthetic records')}</div>
    <div class="grid split"><section class="card"><div class="card-head"><div><h3>Recent requests</h3><p>Live status from the shared transfer state</p></div><select class="select" id="requestFilter"><option value="all">All statuses</option><option value="open">Open only</option><option value="completed">Completed</option></select></div><div id="requestTable">${transferTable(mine)}</div></section>
    <aside class="grid"><section class="card"><div class="card-head"><div><h3>Quick actions</h3><p>Common ward tasks</p></div></div><div class="card-body quick-actions"><button class="quick-action" id="quickNew"><span>＋</span><b>New request</b><small>Book an IFT</small></button><button class="quick-action" data-role-jump="live"><span>◉</span><b>Live board</b><small>View operations</small></button><button class="quick-action" id="exportMine"><span>⇩</span><b>My records</b><small>Download CSV</small></button><button class="quick-action" id="showHelp"><span>?</span><b>Workflow</b><small>Approval guide</small></button></div></section>
    <section class="notice warn"><span>●</span><div><b>Interstate gate is enforced</b>Any destination outside Kedah must receive emergency physician approval before operational approval or ambulance assignment.</div></section></aside></div>`;
  newBooking.onclick=quickNew.onclick=()=>{requesterMode='form';renderRequester()};
  requestFilter.onchange=e=>{const v=e.target.value;const rows=v==='all'?mine:v==='open'?open:mine.filter(t=>t.status==='completed');requestTable.innerHTML=transferTable(rows);bindCommon()};
  exportMine.onclick=()=>exportEnhanced(mine,'hsb-transfers'); showHelp.onclick=()=>openWorkflow();
  document.querySelectorAll('[data-role-jump]').forEach(x=>x.onclick=()=>setRole(x.dataset.roleJump));
}

function renderBookingForm(){
  const checks=(['IV Drip','Ventilator','Neonatal Incubator','Syringe Pump 1-2 set','Syringe Pump 3-4 set','Syringe Pump 5-6 set','Airborne Precaution','Contact Precaution','Droplet Precaution']).map(x=>`<label class="choice"><input type="checkbox" name="needs" value="${x}"> ${x}</label>`).join('');
  app.innerHTML=pageHead('New transfer request','All entries in this prototype must be fictional. Required fields are marked.',`<button class="btn" id="backRequester">← Back to requests</button>`)+`<form class="card form-card" id="bookingForm">
  <div class="form-section"><div class="section-title"><span class="section-number">1</span><div><h3>Patient and clinical details</h3><p>Use synthetic identifiers only.</p></div></div><div class="form-grid">
    <div class="field span-6"><label>Patient name <em>*</em></label><input name="patient" required placeholder="e.g. SYNTHETIC PATIENT 1001"></div><div class="field span-6"><label>IC / passport <em>*</em></label><input name="ic" required placeholder="SYN-000000"></div>
    <div class="field"><label>Age <em>*</em></label><input name="age" type="number" min="0" required></div><div class="field"><label>Age unit <em>*</em></label><select name="ageUnit"><option value="Y">Years</option><option value="M">Months</option><option value="D">Days</option><option value="N">Neonate</option></select></div><div class="field"><label>Gender <em>*</em></label><select name="gender"><option>Female</option><option>Male</option><option>Other / not recorded</option></select></div>
    <div class="field"><label>Triage <em>*</em></label><select name="triage"><option>Routine</option><option>Urgent</option><option>Emergency</option></select></div><div class="field span-8"><label>Patient diagnosis <em>*</em></label><input name="diagnosis" required placeholder="Synthetic diagnosis"></div><div class="field span-12"><label>Reason for referral / transfer <em>*</em></label><textarea name="reason" required></textarea></div>
  </div></div>
  <div class="form-section"><div class="section-title"><span class="section-number">2</span><div><h3>Route and schedule</h3><p>Requesting facility is fixed to HSB for this pilot.</p></div></div><div class="form-grid">
    <div class="field"><label>Requesting facility</label><input value="Hospital Sultanah Bahiyah" disabled></div><div class="field"><label>Requesting unit <em>*</em></label><input name="unit" required placeholder="Ward / department"></div><div class="field"><label>Referring doctor / specialist <em>*</em></label><input name="referrer" required></div>
    <div class="field span-6"><label>Destination facility <em>*</em></label><input name="destination" required></div><div class="field span-6"><label>Destination state <em>*</em></label><select name="destinationState">${STATES.map(x=>`<option>${x}</option>`).join('')}</select></div>
    <div class="field span-6"><label>Pick-up point <em>*</em></label><input name="pickup" required></div><div class="field span-6"><label>Drop-off point <em>*</em></label><input name="dropoff" required></div><div class="field span-6"><label>Requested transfer date and time <em>*</em></label><input name="scheduledAt" type="datetime-local" required></div><div class="field span-6"><label>Return trip required?</label><select name="returnTrip" id="returnTrip"><option>No</option><option>Yes</option></select></div><div class="field span-6" id="returnTimeField" hidden><label>Return trip time</label><input name="returnTime" type="datetime-local"></div>
  </div><div class="notice warn" id="gateNotice" style="margin-top:15px" hidden><span>●</span><div><b>Emergency physician approval required</b>This interstate request will enter medical review before KADCC can approve or assign a vehicle.</div></div></div>
  <div class="form-section"><div class="section-title"><span class="section-number">3</span><div><h3>Mobility, oxygen and equipment</h3><p>These fields map to the legacy iSPRINT dataset.</p></div></div><div class="form-grid"><div class="field span-6"><label>Mobility requirement <em>*</em></label><select name="mobility"><option>Walking</option><option>Wheelchair</option><option>Stretcher</option><option>Carried</option></select></div><div class="field span-6"><label>Oxygen requirement</label><select name="oxygen"><option>None</option><option>1-3 L/m</option><option>4-8 L/m</option><option>9-15 L/m</option></select></div><div class="field span-12"><label>Equipment and precautions</label><div class="choice-grid">${checks}</div></div></div></div>
  <div class="form-section"><div class="section-title"><span class="section-number">4</span><div><h3>Escort and requester</h3><p>Contact information is fictional for this demo.</p></div></div><div class="form-grid"><div class="field"><label>Accompanying team <em>*</em></label><select name="escort"><option>SN / MA</option><option>Medical Officer + SN</option><option>SN + PPK</option><option>Specialist + SN</option><option>Parent / guardian + SN</option></select></div><div class="field"><label>Requesting staff name <em>*</em></label><input name="requester" required value="Nur Aina"></div><div class="field"><label>Contact number <em>*</em></label><input name="contact" required value="04-700 0000"></div><div class="field span-6"><label>Email</label><input name="email" type="email" value="demo.requester@invalid.example"></div><div class="field span-6"><label>Requester remarks</label><textarea name="remark" placeholder="Operational notes for KADCC"></textarea></div></div></div>
  <div class="form-actions"><button type="button" class="btn" id="saveDraft">Save draft locally</button><button type="submit" class="btn primary">Submit transfer request</button></div></form>`;
  backRequester.onclick=()=>{requesterMode='dashboard';renderRequester()};
  returnTrip.onchange=e=>returnTimeField.hidden=e.target.value!=='Yes';
  bookingForm.destinationState.onchange=e=>gateNotice.hidden=e.target.value==='Kedah';
  saveDraft.onclick=()=>toast('Draft saved','Stored in this browser only for the demo.');
  bookingForm.onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const dest=f.get('destinationState');const needs=f.getAll('needs');const id=uid();const at=nowIso();const t={id,patient:f.get('patient'),ic:f.get('ic'),age:f.get('age'),ageUnit:f.get('ageUnit'),gender:f.get('gender'),triage:f.get('triage'),reason:f.get('reason'),requestingFacility:'Hospital Sultanah Bahiyah',unit:f.get('unit'),referrer:f.get('referrer'),destination:f.get('destination'),destinationState:dest,pickup:f.get('pickup'),dropoff:f.get('dropoff'),requestedAt:at,scheduledAt:new Date(f.get('scheduledAt')).toISOString(),diagnosis:f.get('diagnosis'),mobility:f.get('mobility'),returnTrip:f.get('returnTrip'),returnTime:f.get('returnTime')?new Date(f.get('returnTime')).toISOString():'',oxygen:f.get('oxygen'),equipment:needs.filter(x=>!x.includes('Precaution')),precautions:needs.filter(x=>x.includes('Precaution')),escort:f.get('escort'),requester:f.get('requester'),contact:f.get('contact'),email:f.get('email'),remark:f.get('remark'),status:dest==='Kedah'?'new':'medical',medicalDecision:dest==='Kedah'?'Not required':'Pending',medicalRemark:'',operationalRemark:'',ambulance:'',driver:'Hafiz Ismail',createdAt:at,updatedAt:at,timestamps:{requested:at},audit:[{at,actor:actor('requester'),action:'Transfer request submitted'},...(dest==='Kedah'?[]:[{at,actor:'System',action:'Interstate approval gate applied'}])]};state.transfers.unshift(t);saveState();requesterMode='dashboard';render();toast('Request submitted',`${id} is now ${dest==='Kedah'?'awaiting KADCC review':'awaiting emergency physician approval'}.`)};
}

function renderOperator(){
  const active=state.transfers.filter(t=>!['completed','cancelled','rejected'].includes(t.status));
  app.innerHTML=pageHead('KADCC command dashboard','Review requests, enforce approval gates, assign resources and close completed transfers.',`<button class="btn" id="operatorExport">⇩ Export queue</button><button class="btn primary" id="refreshBtn">↻ Refresh state</button>`)+
  `<div class="grid metrics">${metric('New requests',active.filter(t=>t.status==='new').length,'Awaiting review','warn')}${metric('Pending medical',active.filter(t=>['medical','clarification'].includes(t.status)).length,'Interstate gate','danger')}${metric('Awaiting vehicle',active.filter(t=>t.status==='approved').length,'Approved requests')}${metric('Active missions',active.filter(t=>['assigned','active'].includes(t.status)).length,'Assigned or moving','live')}</div>
  <section class="card"><div class="card-head"><div><h3>Transfer queue</h3><p>Select a record to manage its operational workflow.</p></div><div class="search-row"><div class="search"><input id="queueSearch" placeholder="Search reference or destination"></div><select class="select" id="queueFilter"><option value="all">All open</option><option value="new">New</option><option value="medical">Medical approval</option><option value="approved">Approved</option><option value="assigned">Assigned</option><option value="active">Active</option><option value="delayed">Delayed</option></select></div></div><div id="queueTable">${transferTable(active,'manage')}</div></section>`;
  const update=()=>{const q=queueSearch.value.toLowerCase();const f=queueFilter.value;const rows=active.filter(t=>(f==='all'||t.status===f)&&(`${t.id} ${t.destination} ${t.patient}`.toLowerCase().includes(q)));queueTable.innerHTML=transferTable(rows,'manage');bindCommon()};queueSearch.oninput=update;queueFilter.onchange=update;operatorExport.onclick=()=>exportEnhanced(active,'kadcc-open-queue');refreshBtn.onclick=()=>{renderOperator();toast('State refreshed','All browser-local role views are up to date.')};
}

function renderPhysician(){
  const pending=state.transfers.filter(t=>['medical','clarification'].includes(t.status));const decided=state.transfers.filter(t=>interstate(t)&&['Approved','Rejected'].includes(t.medicalDecision));
  app.innerHTML=pageHead('Interstate medical approval','Only transfers to destinations outside Kedah appear for emergency physician review.',`<button class="btn" id="medicalPolicy">View gate policy</button>`)+
  `<div class="grid metrics">${metric('Awaiting decision',pending.length,'Mandatory interstate reviews','warn')}${metric('Urgent / emergency',pending.filter(t=>t.triage!=='Routine').length,'Prioritised cases','danger')}${metric('Approved today',decided.filter(t=>t.medicalDecision==='Approved').length,'Synthetic records','live')}${metric('Rejected today',decided.filter(t=>t.medicalDecision==='Rejected').length,'Synthetic records')}</div>
  <div class="grid split"><section class="card"><div class="card-head"><div><h3>Medical review queue</h3><p>Clinical data view with approval, rejection and clarification actions</p></div></div>${pending.length?pending.map(t=>`<div class="card-body" style="border-bottom:1px solid var(--line)"><div style="display:flex;justify-content:space-between;gap:12px"><div><span class="kicker">${t.id} · ${t.triage}</span><h3 style="margin:5px 0">${escapeHtml(t.patient)} → ${escapeHtml(t.destination)}</h3><p class="muted" style="margin:0">${escapeHtml(t.diagnosis)} · ${escapeHtml(t.mobility)} · Oxygen: ${escapeHtml(t.oxygen)}</p></div>${statusChip(t.status)}</div><div class="actions" style="margin-top:15px"><button class="btn small" data-detail="${t.id}">Full data</button><button class="btn small danger" data-med-action="reject" data-id="${t.id}">Reject</button><button class="btn small" data-med-action="clarify" data-id="${t.id}">Request clarification</button><button class="btn small primary" data-med-action="approve" data-id="${t.id}">Approve medically</button></div></div>`).join(''):`<div class="empty"><div class="empty-icon">✓</div>No interstate transfers are waiting for review.</div>`}</section>
  <aside class="card"><div class="card-head"><div><h3>Recent decisions</h3><p>Emergency physician audit activity</p></div></div><div class="card-body activity">${decided.slice(0,5).map(t=>`<div class="activity-item"><span class="activity-dot"></span><div><p><b>${t.medicalDecision}</b> · ${t.id}<br><span class="muted">${escapeHtml(t.destination)}</span></p><time>${fmt(t.timestamps.medicalApproved||t.updatedAt)}</time></div></div>`).join('')||'<div class="empty">No decisions yet.</div>'}</div></aside></div>`;
  medicalPolicy.onclick=openWorkflow;document.querySelectorAll('[data-med-action]').forEach(b=>b.onclick=()=>medicalAction(b.dataset.id,b.dataset.medAction));
}

function renderManager(){
 const total=state.transfers;const completed=total.filter(t=>t.status==='completed').length;const interstateCount=total.filter(interstate).length;
 app.innerHTML=pageHead('Operations oversight','Live performance, transfer activity and iSPRINT-compatible reporting.',`<select class="select" id="periodSelect"><option>Daily · 13 Oct 2026</option><option>Monthly · October 2026</option><option>Yearly · 2026</option></select><button class="btn primary" id="exportLegacyTop">⇩ iSPRINT export</button>`)+
 `<div class="grid metrics">${metric('Transfers',total.length,'Selected reporting period')}${metric('Completion rate',`${Math.round(completed/Math.max(total.length,1)*100)}%`,'Closed cases','live')}${metric('Interstate',interstateCount,'Medical approval required','warn')}${metric('Active now',total.filter(t=>['assigned','active'].includes(t.status)).length,'Operational workload','live')}</div>
 <div class="grid split"><section class="card"><div class="card-head"><div><h3>Transfer activity</h3><p>Requests and completed transfers by operational period</p></div><div class="legend"><span>Requests</span><span>Completed</span></div></div><div class="card-body"><div class="chart">${[42,63,48,77,58,86,69].map((h,i)=>`<div class="bar-group"><div class="bar" style="height:${h}%"></div><div class="bar secondary" style="height:${Math.max(12,h-18)}%"></div><label>${['07','08','09','10','11','12','13'][i]} Oct</label></div>`).join('')}</div></div></section><aside class="card"><div class="card-head"><div><h3>Attention required</h3><p>Current workflow exceptions</p></div></div><div class="card-body activity">${state.transfers.filter(t=>['medical','clarification','delayed'].includes(t.status)).map(t=>`<div class="activity-item"><span class="activity-dot"></span><div><p><b>${STATUS_LABELS[t.status]}</b> · ${t.id}<br><span class="muted">${escapeHtml(t.destination)}</span></p><time>Updated ${fmt(t.updatedAt)}</time></div></div>`).join('')||'<div class="empty">No exceptions.</div>'}</div></aside></div>
 <section class="card" style="margin-top:18px"><div class="card-head"><div><h3>Reports & exports</h3><p>Legacy compatibility and enhanced operational data</p></div></div><div class="card-body grid report-grid"><div class="card report-card"><div class="icon">65</div><h3>iSPRINT compatible</h3><p>Exact original 65 column names and order. Blank values are preserved where not applicable.</p><button class="btn" id="exportLegacy">Download 65-column CSV</button></div><div class="card report-card"><div class="icon">＋</div><h3>InFacT enhanced</h3><p>Transfer state, interstate gate, medical remarks, audit details and additional timestamps.</p><button class="btn" id="exportEnhanced">Download enhanced CSV</button></div><div class="card report-card"><div class="icon">▦</div><h3>Filtered report</h3><p>Daily, monthly and yearly views use the current period selector in this prototype.</p><button class="btn" id="exportPeriod">Download current period</button></div></div></section>`;
 exportLegacy.onclick=exportLegacyTop.onclick=()=>exportLegacy(state.transfers);exportEnhanced.onclick=()=>exportEnhanced(state.transfers);exportPeriod.onclick=()=>exportEnhanced(state.transfers,'infact-period-report');periodSelect.onchange=()=>toast('Reporting period changed',periodSelect.value);
}

function renderPilot(){
 const mine=state.transfers.filter(t=>t.driver==='Hafiz Ismail'&&['assigned','active'].includes(t.status));
 app.innerHTML=pageHead('My assigned missions','Accept assignments and record journey milestones. Timestamps are added automatically.',`<button class="btn" id="pilotRefresh">↻ Refresh assignments</button>`)+
 `<div class="grid metrics">${metric('Assigned missions',mine.length,'Driver: Hafiz Ismail','live')}${metric('Ready to depart',mine.filter(t=>t.status==='assigned').length,'Accepted or pending')}${metric('In progress',mine.filter(t=>t.status==='active').length,'Patient journey active','warn')}${metric('Completed today',state.transfers.filter(t=>t.driver==='Hafiz Ismail'&&t.status==='completed').length,'Closed by KADCC')}</div>
 <div class="grid">${mine.length?mine.map(t=>`<section class="card mission"><div class="card-body"><div class="mission-hero"><span class="kicker" style="color:#aee3dd">${t.id} · ${t.triage}</span><div class="route">${escapeHtml(t.pickup)} → ${escapeHtml(t.destination)}</div><p>${escapeHtml(t.ambulance)} · Scheduled ${fmt(t.scheduledAt)}</p></div><div class="detail-grid"><div class="detail-item"><small>Patient</small><b>${escapeHtml(t.patient)}</b></div><div class="detail-item"><small>Mobility</small><b>${escapeHtml(t.mobility)}</b></div><div class="detail-item"><small>Oxygen</small><b>${escapeHtml(t.oxygen)}</b></div></div>${workflow(t)}<div class="mission-actions" style="margin-top:22px">${pilotButtons(t)}</div><div class="notice" style="margin-top:15px"><span>i</span><div>GPS fields remain blank in this browser demo. Production mobile capture requires approved device permissions, security controls and KKM governance.</div></div></div></section>`).join(''):`<section class="card"><div class="empty"><div class="empty-icon">✓</div>No current missions assigned to this pilot.</div></section>`}</div>`;
 pilotRefresh.onclick=()=>{renderPilot();toast('Assignments refreshed','Shared browser state is current.')};document.querySelectorAll('[data-pilot-step]').forEach(b=>b.onclick=()=>pilotStep(b.dataset.id,b.dataset.pilotStep));
}

function workflow(t){const steps=[['accepted','Accepted'],['departed','Departed'],['pickupArrival','At pickup'],['onBoard','On board'],['destinationArrival','At destination']];const current=steps.findIndex(([k])=>!t.timestamps[k]);return `<div class="workflow">${steps.map(([k,l],i)=>`<div class="step ${t.timestamps[k]?'done':i===current?'current':''}"><i>${t.timestamps[k]?'✓':i+1}</i><span>${l}</span></div>`).join('')}</div>`}
function pilotButtons(t){const s=t.timestamps;if(!s.accepted)return `<button class="btn primary" data-pilot-step="accepted" data-id="${t.id}">Accept mission</button>`;if(!s.departed)return `<button class="btn primary" data-pilot-step="departed" data-id="${t.id}">Mark departed</button>`;if(!s.pickupArrival)return `<button class="btn primary" data-pilot-step="pickupArrival" data-id="${t.id}">Arrived at pickup</button>`;if(!s.onBoard)return `<button class="btn primary" data-pilot-step="onBoard" data-id="${t.id}">Patient on board</button>`;if(!s.destinationArrival)return `<button class="btn primary" data-pilot-step="destinationArrival" data-id="${t.id}">Arrived at destination</button>`;return `<button class="btn" disabled>Awaiting KADCC closure</button>`}

function renderLive(){
 const lanes=[['Waiting',['new','medical','clarification','delayed']],['Ready',['approved']],['Assigned',['assigned']],['In progress',['active']]];
 app.innerHTML=pageHead('Live transfer board','Shared operational view. Patient identifiers are intentionally minimised on this screen.',`<span class="sync"><span></span> Updated just now</span><button class="btn" id="liveRefresh">↻ Refresh</button>`)+
 `<div class="notice" style="margin-bottom:18px"><span>◉</span><div><b>Operational display mode</b>This board shows reference numbers, routes, priorities and resource status. Open role-specific views for authorised clinical detail.</div></div><div class="kanban">${lanes.map(([label,statuses])=>{const items=state.transfers.filter(t=>statuses.includes(t.status));return `<section class="lane"><div class="lane-head">${label}<span>${items.length}</span></div>${items.map(t=>`<article class="transfer-card"><div class="top"><b class="ref">${t.id}</b>${statusChip(t.status)}</div><div class="route">${escapeHtml(t.unit)} → ${escapeHtml(t.destination)}<small>${escapeHtml(t.destinationState)}${interstate(t)?' · Interstate':''}</small></div><div class="transfer-meta"><span class="priority ${t.triage.toLowerCase()}">${t.triage}</span><span>${t.ambulance?escapeHtml(t.ambulance.split(' · ')[0]):'Vehicle pending'}</span></div></article>`).join('')||'<div class="empty">No transfers</div>'}</section>`}).join('')}</div>`;liveRefresh.onclick=()=>{renderLive();toast('Live board refreshed','All operational statuses are current.')};
}

function openDetail(id){const t=state.transfers.find(x=>x.id===id);if(!t)return;const operatorActions=activeRole==='operator'?operatorActionHtml(t):'';
 openModal(`<div class="modal-head"><span class="kicker">${t.id} · ${interstate(t)?'Interstate':'Within Kedah'}</span><h2 id="modalTitle">${escapeHtml(t.patient)}</h2><p>${escapeHtml(t.requestingFacility)} → ${escapeHtml(t.destination)}</p></div><div class="tabs"><button class="tab active">Transfer data</button><button class="tab">Audit trail (${t.audit.length})</button></div><div class="modal-body"><div class="notice ${interstate(t)?'warn':''}" style="margin-bottom:18px"><span>●</span><div><b>${interstate(t)?`Medical gate: ${t.medicalDecision}`:'Medical approval not required'}</b>${interstate(t)?'Destination is outside Kedah. KADCC approval remains blocked until medical approval is recorded.':'This request can proceed directly to KADCC operational review.'}</div></div><div class="detail-grid">${[['Status',STATUS_LABELS[t.status]],['Triage',t.triage],['Requested',fmt(t.requestedAt)],['Diagnosis',t.diagnosis],['Reason',t.reason],['Mobility',t.mobility],['Oxygen',t.oxygen],['Escort',t.escort],['Pick-up',t.pickup],['Drop-off',t.dropoff],['Ambulance',t.ambulance||'Not assigned'],['Scheduled',fmt(t.scheduledAt)]].map(([a,b])=>`<div class="detail-item"><small>${a}</small><b>${escapeHtml(b)}</b></div>`).join('')}</div><div class="divider"></div><h3 style="font:700 14px Manrope">Remarks</h3><p><b>Requester:</b> ${escapeHtml(t.remark||'—')}</p><p><b>Medical:</b> ${escapeHtml(t.medicalRemark||'—')}</p><p><b>Operations:</b> ${escapeHtml(t.operationalRemark||'—')}</p><div class="divider"></div><h3 style="font:700 14px Manrope">Audit trail</h3><div class="activity">${t.audit.map(a=>`<div class="activity-item"><span class="activity-dot"></span><div><p><b>${escapeHtml(a.action)}</b><br><span class="muted">${escapeHtml(a.actor)}</span></p><time>${fmt(a.at)}</time></div></div>`).join('')}</div></div>${operatorActions}`);
 document.querySelectorAll('[data-op-action]').forEach(b=>b.onclick=()=>operatorAction(id,b.dataset.opAction));
}
function operatorActionHtml(t){if(['completed','cancelled','rejected'].includes(t.status))return `<div class="modal-actions"><button class="btn" onclick="closeModal()">Close</button></div>`;const gate=interstate(t)&&t.medicalDecision!=='Approved';return `<div class="modal-actions"><button class="btn danger" data-op-action="cancel">Cancel</button><button class="btn" data-op-action="delay">Delay</button>${['new','delayed'].includes(t.status)?`<button class="btn primary" data-op-action="approve" ${gate?'disabled title="Medical approval required"':''}>Operational approve</button>`:''}${t.status==='approved'?`<button class="btn primary" data-op-action="assign">Assign ambulance</button>`:''}${t.status==='active'&&t.timestamps.destinationArrival?`<button class="btn primary" data-op-action="complete">Close transfer</button>`:''}${gate?`<span class="chip medical">Blocked by medical gate</span>`:''}</div>`}

function operatorAction(id,action){const t=state.transfers.find(x=>x.id===id);if(!t)return;
 if(action==='delay'){requestAction('Delay transfer','Reason for delay','Awaiting receiving facility confirmation','Record delay',r=>{t.status='delayed';t.operationalRemark=r;addAudit(t,`Transfer delayed: ${r}`);finishOperatorUpdate(t)});return}
 if(action==='cancel'){requestAction('Cancel transfer','Reason for cancellation','Request withdrawn','Cancel transfer',r=>{t.status='cancelled';t.operationalRemark=r;addAudit(t,`Transfer cancelled: ${r}`);finishOperatorUpdate(t)});return}
 if(action==='approve'){if(interstate(t)&&t.medicalDecision!=='Approved'){toast('Approval blocked','Emergency physician approval is mandatory for interstate transfers.');return}t.status='approved';t.timestamps.approved=nowIso();addAudit(t,'Operationally approved')}
 if(action==='assign'){t.status='assigned';t.ambulance='KDH 1887 · HSB 02';t.driver='Hafiz Ismail';t.timestamps.assigned=nowIso();addAudit(t,'Ambulance KDH 1887 assigned')}
 if(action==='complete'){t.status='completed';t.timestamps.completed=nowIso();addAudit(t,'Patient handover confirmed; transfer completed and closed')}
 finishOperatorUpdate(t)}
function finishOperatorUpdate(t){saveState();closeModal();render();toast('Transfer updated',`${t.id}: ${STATUS_LABELS[t.status]}.`)}
function medicalAction(id,action){const t=state.transfers.find(x=>x.id===id);if(!t||!interstate(t))return;const title=action==='approve'?'Approve interstate transfer':action==='reject'?'Reject interstate transfer':'Request clinical clarification';const label=action==='approve'?'Medical approval remarks':action==='reject'?'Reason for rejection':'Information required';const initial=action==='approve'?'Medically fit for transfer with documented escort and equipment.':'Please provide additional clinical information.';requestAction(title,label,initial,action==='approve'?'Approve medically':action==='reject'?'Reject transfer':'Send clarification request',r=>{t.medicalRemark=r;if(action==='approve'){t.medicalDecision='Approved';t.status='new';t.timestamps.medicalApproved=nowIso();addAudit(t,'Interstate transfer medically approved')}else if(action==='reject'){t.medicalDecision='Rejected';t.status='rejected';addAudit(t,'Interstate transfer medically rejected')}else{t.medicalDecision='Clarification requested';t.status='clarification';addAudit(t,'Clinical clarification requested')}saveState();closeModal();render();toast('Medical decision recorded',`${id}: ${t.medicalDecision}.`)})}
function requestAction(title,label,initial,confirmLabel,onConfirm){openModal(`<form id="actionForm"><div class="modal-head"><span class="kicker">Decision record</span><h2 id="modalTitle">${escapeHtml(title)}</h2><p>The remark and timestamp will be added to the audit history.</p></div><div class="modal-body"><div class="field span-12"><label for="actionReason">${escapeHtml(label)} <em>*</em></label><textarea id="actionReason" required>${escapeHtml(initial)}</textarea></div></div><div class="modal-actions"><button type="button" class="btn" id="actionCancel">Back</button><button type="submit" class="btn primary">${escapeHtml(confirmLabel)}</button></div></form>`);actionCancel.onclick=closeModal;actionForm.onsubmit=e=>{e.preventDefault();const value=actionReason.value.trim();if(value)onConfirm(value)}}
function pilotStep(id,step){const t=state.transfers.find(x=>x.id===id);if(!t)return;const labels={accepted:'Mission accepted',departed:'Ambulance departed',pickupArrival:'Arrived at pick-up point',onBoard:'Patient on board',destinationArrival:'Arrived at destination'};t.timestamps[step]=nowIso();if(step!=='accepted')t.status='active';addAudit(t,labels[step]);saveState();render();toast(labels[step],`${id} timestamp recorded.`)}

function legacyRow(t){const yes=x=>x?'Yes':'';const oxy=t.oxygen||'';const eq=t.equipment||[];const pr=t.precautions||[];const approvedBy=t.medicalDecision==='Approved'?'Dr. Sofia Karim':t.timestamps.approved?'Farid Rahman':'';return {
 "iSPRINT ID":t.id,"Timestamp":t.createdAt,"Patient's Name":t.patient,"Patient's IC/Passport":t.ic,"Patient's Age":t.age,"Y/M/D/N":t.ageUnit,"Patient's Gender":t.gender,"Triage":t.triage,"Reason of Referral/Transfer":t.reason,"Requesting Facility":t.requestingFacility,"Requesting Unit":t.unit,"Referring Doctor/Specialist":t.referrer,"Destination Facility":t.destination,"Pick-up-Point":t.pickup,"Drop-off Point":t.dropoff,"Requesting Timestamp":t.requestedAt,"Accompanying Doctor":yes(t.escort?.includes('Doctor')||t.escort?.includes('Medical Officer')||t.escort?.includes('Specialist')),"Accompanying SN/MA":yes(t.escort?.includes('SN')||t.escort?.includes('MA')),"Accompanying PPK":yes(t.escort?.includes('PPK')),"Requesting Staff Name":t.requester,"Requesting Staff Contact No.":t.contact,"Requesting Staff Email":t.email,"Patient's Diagnosis":t.diagnosis,"Mobility Requirement":t.mobility,"Return Trip Required?":t.returnTrip,"Return Trip Time":t.returnTime||'',"Oxygen 1-3 L/m":yes(oxy==='1-3 L/m'),"Oxygen 4-8 L/m":yes(oxy==='4-8 L/m'),"Oxygen 9-15 L/m":yes(oxy==='9-15 L/m'),"IV Drip":yes(eq.includes('IV Drip')),"Ventilator":yes(eq.includes('Ventilator')),"Neonatal Incubator":yes(eq.includes('Neonatal Incubator')),"Syringe Pump 1-2 set":yes(eq.includes('Syringe Pump 1-2 set')),"Syringe Pump 3-4 set":yes(eq.includes('Syringe Pump 3-4 set')),"Syringe Pump 5-6 set":yes(eq.includes('Syringe Pump 5-6 set')),"Airborne Precaution":yes(pr.includes('Airborne Precaution')),"Contact Precaution":yes(pr.includes('Contact Precaution')),"Droplet Precaution":yes(pr.includes('Droplet Precaution')),"Requesting Staff Remark":t.remark,"Request Approval":t.medicalDecision==='Rejected'?'Rejected':STATUS_LABELS[t.status],"Approval Timestamp":t.timestamps.medicalApproved||t.timestamps.approved||'',"Approved By":approvedBy,"Retrieval":t.returnTrip==='Yes'?'Yes':'No',"Retrieval Case ID":"","Vehicle Assignment":t.ambulance,"Manager's Remark":t.operationalRemark,"Pick-up Point Arrival Timestamp":t.timestamps.pickupArrival||'',"Pick-up Point Arrival Latitude":"","Pick-up Point Arrival Longitude":"","Enroute 1 Timestamp":t.timestamps.departed||'',"Enroute 1 Latitute":"","Enroute 1 Longitude":"","At Destination 1 Timestamp":t.timestamps.destinationArrival||'',"At Destination 1 Latitute":"","At Destination 1 Longitude":"","Enroute 2 Timestamp":"","Enroute 2 Latitute":"","Enroute 2 Longitude":"","At Destination 2 Timestamp":"","At Destination 2 Latitute":"","At Destination 2 Longitude":"","Completion Timestamp":t.timestamps.completed||'',"Case Progress":STATUS_LABELS[t.status],"MECC Backup":"No","Referral Letter":""};}
function csvCell(v){return `"${String(v??'').replaceAll('"','""')}"`}
function downloadCsv(rows,columns,name){const csv='\uFEFF'+[columns.map(csvCell).join(','),...rows.map(r=>columns.map(c=>csvCell(r[c])).join(','))].join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${name}-${new Date().toISOString().slice(0,10)}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Export ready',`${rows.length} synthetic record${rows.length===1?'':'s'} downloaded.`)}
function exportLegacy(items=state.transfers){downloadCsv(items.map(legacyRow),LEGACY_COLUMNS,'isprint-compatible-65-columns')}
function exportEnhanced(items=state.transfers,name='infact-enhanced'){const cols=[...LEGACY_COLUMNS,'Destination State','Interstate Transfer','Medical Approval Decision','Medical Approval Remark','Operational Remark','Assigned Driver','Scheduled Transfer Timestamp','Accepted Timestamp','Departed Timestamp','Patient On Board Timestamp','Audit Trail JSON'];const rows=items.map(t=>({...legacyRow(t),'Destination State':t.destinationState,'Interstate Transfer':interstate(t)?'Yes':'No','Medical Approval Decision':t.medicalDecision,'Medical Approval Remark':t.medicalRemark,'Operational Remark':t.operationalRemark,'Assigned Driver':t.driver,'Scheduled Transfer Timestamp':t.scheduledAt,'Accepted Timestamp':t.timestamps.accepted||'','Departed Timestamp':t.timestamps.departed||'','Patient On Board Timestamp':t.timestamps.onBoard||'','Audit Trail JSON':JSON.stringify(t.audit)}));downloadCsv(rows,cols,name)}

function openWorkflow(){openModal(`<div class="modal-head"><span class="kicker">Enforced workflow</span><h2 id="modalTitle">Kedah and interstate routes</h2><p>The gate is evaluated from the selected destination state.</p></div><div class="modal-body"><div class="grid split"><div class="notice"><span>✓</span><div><b>Destination within Kedah</b>Requester → KADCC operational review → Ambulance assignment → Journey → Closure</div></div><div class="notice warn"><span>●</span><div><b>Destination outside Kedah</b>Requester → Emergency physician approval → KADCC operational review → Ambulance assignment → Journey → Closure</div></div></div><div class="divider"></div><p>If an interstate request has not been medically approved, the operator's approval button is disabled. Rejected cases cannot progress. Clarification returns the case to the physician queue.</p></div><div class="modal-actions"><button class="btn primary" onclick="closeModal()">Understood</button></div>`)}
function openSecurity(){openModal(`<div class="modal-head"><span class="kicker">Production boundary</span><h2 id="modalTitle">Demo-only architecture</h2><p>This interactive prototype is suitable for workflow evaluation with synthetic data only.</p></div><div class="modal-body"><div class="notice danger"><span>!</span><div><b>Do not enter real patient information</b>Authentication is simulated and data is stored in this browser's local storage. It is not a clinical system.</div></div><div class="divider"></div><h3>KKM-approved deployment must add</h3><div class="security-list">${['Formal identity, MFA and server-enforced role-based access','Approved encrypted database, backups, retention and disaster recovery','Encryption in transit and at rest with managed keys','Immutable audit logs, monitoring and security incident response','Clinical safety, privacy impact and KKM governance reviews','Penetration testing, vulnerability management and approved hosting location','Integration controls for patient, ambulance and hospital systems'].map((x,i)=>`<div><i>${i+1}</i><span><b>${x}</b><small>Required before any production or patient-data use.</small></span></div>`).join('')}</div></div><div class="modal-actions"><button class="btn primary" onclick="closeModal()">Close</button></div>`)}
function openAbout(){openModal(`<div class="modal-head"><span class="kicker">InFacT MVP 1.0</span><h2 id="modalTitle">Functional workflow prototype</h2><p>KADCC + Hospital Sultanah Bahiyah pilot</p></div><div class="modal-body"><p>Six connected role views use one browser-local state. The prototype demonstrates HSB request capture, mandatory interstate medical approval, operational coordination, ambulance assignment, journey updates, closure, audit history and two export formats.</p><p>The legacy download preserves all <b>65 original iSPRINT column names in their exact source order</b>, including source spelling.</p></div><div class="modal-actions"><button class="btn primary" onclick="closeModal()">Close</button></div>`)}
function openModal(html){modalContent.innerHTML=html;modalBackdrop.hidden=false;document.body.style.overflow='hidden'}window.closeModal=function(){modalBackdrop.hidden=true;document.body.style.overflow=''};
function toast(title,message){const el=document.createElement('div');el.className='toast';el.innerHTML=`<b>${escapeHtml(title)}</b><small>${escapeHtml(message)}</small>`;toastWrap.appendChild(el);setTimeout(()=>el.remove(),3600)}

roleNav.onclick=e=>{const b=e.target.closest('[data-role]');if(b)setRole(b.dataset.role)};profileBtn.onclick=()=>profileMenu.classList.toggle('open');menuBtn.onclick=()=>sidebar.classList.toggle('open');modalClose.onclick=closeModal;modalBackdrop.onclick=e=>{if(e.target===modalBackdrop)closeModal()};resetBtn.onclick=resetState;aboutBtn.onclick=openAbout;securityBtn.onclick=openSecurity;bellBtn.onclick=()=>toast('Notifications',`${state.transfers.filter(t=>t.status==='medical').length} medical review${state.transfers.filter(t=>t.status==='medical').length===1?'':'s'} pending.`);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
render();
